mapper.select:
select id, settlement_date_begin, settlement_date_end, exchange_rate, source_currency_code, target_currency_code, update_time
from bi_settlement_exchange_rate

    source_currency_code = #{sourceCurrencyCode}
    and target_currency_code = 'CNY'
    and settlement_date_begin <= #{date}
    and settlement_date_end >= #{date}
    and approve_status = 'approve'
    and disabled = false
    and type = 'HLTX01_SYS'
